                ceiling = limits[kind]
                held = self.store.connection.execute(
                    f"SELECT COUNT(*) AS held FROM {kind} WHERE tenant = ?",
                    (tenant,),
                ).fetchone()["held"]
                status[kind] = {"limit": ceiling, "held": held, "remaining": ceiling - held}
            return {"status": status}

